import{_ as p,C as e,o,c as i,E as a,a2 as d}from"./chunks/framework.Cm6XCzck.js";const m=JSON.parse('{"title":"批准了这条命令，为什么另一条也能过？一次 Agent 授权摘要实验","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"批准了这条命令，为什么另一条也能过？一次 Agent 授权摘要实验","date":"2026-09-04","published_date":"2026-09-04","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"实际工具入口是否保留了批准必须绑定的动作区别，并将会话上下文与动作身份正确分开？","summary":"在同一条 Agent 审批链上，改 Git 分支没有改变授权摘要，只换 Session 却改变了摘要。真实服务、跨进程记录和正反对照揭示：风险分类、动作身份与执行授权，不能交给同一个含糊的‘相同’。","cover":"/assets/approval-identity-20260904/assets/approval-identity-cover-v2.png","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled experiments on a fixed baseline; no fix or independent QA claimed","sources":["https://github.com/openai/codex/pull/42588","https://github.com/openai/codex/pull/42579"]},"headers":[],"relativePath":"zh/engineering/2026-09-04-approval-operation-identity.md","filePath":"zh/engineering/2026-09-04-approval-operation-identity.md","lastUpdated":1788532182000}'),r={name:"zh/engineering/2026-09-04-approval-operation-identity.md"};function l(c,t,h,g,u,b){const s=e("ArticleCover"),n=e("ArticleTableScroll");return o(),i("div",null,[a(s,{image:"/assets/approval-identity-20260904/assets/approval-identity-cover-v2.png",kicker:"开源工程观察 · 受控实验",title:"批准了这条命令，为什么另一条也能过？一次 Agent 授权摘要实验",summary:"在同一条 Agent 审批链上，改 Git 分支没有改变授权摘要，只换 Session 却改变了摘要。真实服务、跨进程记录和正反对照揭示：风险分类、动作身份与执行授权，不能交给同一个含糊的‘相同’。",version:"2026-09-04",languageHref:"/en/engineering/2026-09-04-approval-operation-identity",languageLabel:"English"}),a(n,{language:"zh"}),t[0]||(t[0]=d(`<h1 id="批准了这条命令-为什么另一条也能过-一次-agent-授权摘要实验" tabindex="-1">批准了这条命令，为什么另一条也能过？一次 Agent 授权摘要实验 <a class="header-anchor" href="#批准了这条命令-为什么另一条也能过-一次-agent-授权摘要实验" aria-label="Permalink to &quot;批准了这条命令，为什么另一条也能过？一次 Agent 授权摘要实验&quot;">​</a></h1><p>我们先为一条命令建立批准记录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin codex/research-probe</span></span></code></pre></div><p>随后保持项目、任务、执行者和会话不变，只换了目标分支：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin codex/another-target</span></span></code></pre></div><p>第二条命令通过了审批判断，第一条命令的批准记录被标为已消费。</p><p>另一组实验更反常：命令没有变，只把会话换成批准记录中登记的唤醒会话，系统却再次要求审批。</p><p><strong>该区分的动作没有区分；本来希望支持的会话续接，反而改变了匹配结果。</strong></p><p>这是一次隔离的受控实验，不是线上推送事故。两条命令都没有真正执行。但决定“是否允许”的代码和批准记录持久化，使用的是真实产品实现。</p><h2 id="_1-我们为什么查这一层" tabindex="-1">1. 我们为什么查这一层 <a class="header-anchor" href="#_1-我们为什么查这一层" aria-label="Permalink to &quot;1. 我们为什么查这一层&quot;">​</a></h2><p>CodeFlowMu 是我们在开发的本地多 Agent 协作系统。它用 FCoP 文件协议保存正式任务及协作记录，任务身份不依赖某一个 Agent 会话持续存活。运行时还要处理另一个问题：Agent 请求一个需要批准的操作时，批准究竟对应什么？</p><p>恢复场景让这个问题变得尖锐。原会话可能中断，新会话可能接替；审批记录还在，任务文件也还在。系统既不能把“记录存在”直接当成执行许可，也不应因为无关的上下文变化，丢失原本可以识别的动作。</p><p>这一轮研究受到 Codex 近期变更的启发。Codex 是 OpenAI 的编码 Agent，Guardian 是其工具安全审核机制的一部分。9 月 3 日合并的 <a href="https://github.com/openai/codex/pull/42588" target="_blank" rel="noreferrer">PR #42588</a> 在特定上下文模式下检查压缩记录的生产者兼容信息；缺失或不兼容时，不能靠省略该记录继续快速批准，而应进入同步审核。另一项 <a href="https://github.com/openai/codex/pull/42579" target="_blank" rel="noreferrer">PR #42579</a> 保留经 Host 核验的用户问答，并在证据不完整时限制快速批准。</p><p>它们处理的是 <strong>Codex 审核证据能否被当前判断使用</strong>，不是本文的 Git 操作摘要缺口，也不意味着 CodeFlowMu 应再造一个 Guardian。我们从中提取的问题更窄：</p><p><strong>一份真实存在的批准记录，为什么适用于眼前这一次调用？</strong></p><p>要回答它，不能只看记录有没有 <code>approved</code>。</p><h2 id="_2-系统并不是没有审批保护" tabindex="-1">2. 系统并不是没有审批保护 <a class="header-anchor" href="#_2-系统并不是没有审批保护" aria-label="Permalink to &quot;2. 系统并不是没有审批保护&quot;">​</a></h2><p>我们把源码固定在 <code>fdadbed489129455437f25202a03bae6e0c2e822</code>，即本次研究采用的 V2.2.8 相关基线，不随之后的 main 漂移。</p><p>先复跑四组既有测试，覆盖操作批准、任务父子身份、证据关联和凭证脱敏。两轮都是 <strong>31 项通过、0 失败、0 跳过</strong>。这是 31 项测试重复两次，不是 62 个独立场景，也不是全量产品验收。</p><p>操作批准测试已经验证了有价值的保护：改变请求目标会被拒绝，批准只消费一次，某些恢复调用可以读取原有记录，手工构造的请求也能支持 Session 续接。</p><p>因此，我们没有直接下结论“缺少审批”或“应该增加幂等”。接下来要检查的是：<strong>实际工具入口构造出来的请求，是否仍具有这些测试假定的身份信息？</strong></p><p>探针先经过真实 Native 审批门，生成待批准记录，再由服务建立批准。随后另起 Node 进程重读记录并请求消费；能通过的调用再由另一个进程尝试重复消费。这里的跨进程是为了排除“只靠内存记住批准”的解释，不是掉电恢复测试。</p><p>11 种输入分别重复两轮，结果一致：</p><table tabindex="0"><thead><tr><th>相对已批准请求的变化</th><th>真实审批门的结果</th><th>批准记录</th></tr></thead><tbody><tr><td>同会话、同动作</td><td>允许；再次请求报已消费</td><td>consumed</td></tr><tr><td>只换成登记的唤醒会话</td><td>再次要求审批</td><td>available</td></tr><tr><td>换成另一个非空会话</td><td>再次要求审批</td><td>available</td></tr><tr><td>不提供会话</td><td>再次要求审批</td><td>available</td></tr><tr><td>改 Agent</td><td>再次要求审批</td><td>available</td></tr><tr><td>改 TASK</td><td>再次要求审批</td><td>available</td></tr><tr><td>改 thread</td><td>再次要求审批</td><td>available</td></tr><tr><td>改 project</td><td>再次要求审批</td><td>available</td></tr><tr><td>同会话，只改 push 分支</td><td><strong>允许；再次请求报已消费</strong></td><td><strong>consumed</strong></td></tr><tr><td>改调用来源渠道</td><td>再次要求审批</td><td>available</td></tr><tr><td>待审批阶段取消，不予批准</td><td>再次要求审批</td><td>invalid</td></tr></tbody></table><p>来源渠道改变是否应被视为等价，需要单独定义，本文不把那一行直接判错。会话行也不能证明真实 successor 已满足全部接管资格；本实验只改变会话输入，并登记对应的唤醒会话。</p><p>最值得追查的是两个反向结果：改分支被接受，只换会话却失配。完整探针保留了这两类预期偏离，每类两次，最终以断言失败退出。没有把它改成一个漂亮的全绿报告。逐轮记录见<a href="/joinwell52/zh/research/evidence/2026-09-04-approval-operation-identity">配套证据说明</a>。</p><h2 id="_3-哈希没有撞-动作信息先丢了" tabindex="-1">3. 哈希没有撞，动作信息先丢了 <a class="header-anchor" href="#_3-哈希没有撞-动作信息先丢了" aria-label="Permalink to &quot;3. 哈希没有撞，动作信息先丢了&quot;">​</a></h2><p>这条审批链有几个不同职责：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>工具名与参数</span></span>
<span class="line"><span>→ 适配器提取操作事实</span></span>
<span class="line"><span>→ 生成操作指纹和审批请求</span></span>
<span class="line"><span>→ 计算请求摘要</span></span>
<span class="line"><span>→ 匹配已批准记录</span></span>
<span class="line"><span>→ 一次消费</span></span></code></pre></div><p>操作指纹用于标识提取后的操作事实；请求摘要则绑定审批请求。两者都不是原始命令的天然替身。</p><p>在受测实现中，shell 适配器能识别 <code>git push</code> 属于远端 Git 写操作，因此首次调用会进入审批。这一层做对了风险分类。</p><p>但它没有把上述命令的 remote、分支引用及 force/delete 区别保留为相应的操作身份信息。探针中的目标数组是空的，完整性标记却仍为 true；后续审批请求也没有补回原始命令中的这些区别。</p><p>于是“都属于远端 Git 写操作”，在后面变成了“是同一个获准操作”。</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/operation-collapse.zh.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/operation-collapse.zh.png" alt="图 1：不同分支命令在提取后生成相同批准对象"></a></p><p><em>图 1：原始命令的差异在摘要计算前已丢失。来源：本次固定基线的字段差分、审批门及本地 Codex resolution 观察；未执行真实推送。点击图片查看高清原图。</em></p><p>我们继续做七组字段差分，每组重复两轮：</p><table tabindex="0"><thead><tr><th>变化</th><th>操作指纹</th><th>请求摘要</th></tr></thead><tbody><tr><td>原样请求</td><td>相同</td><td>相同</td></tr><tr><td>改目标分支</td><td>相同</td><td>相同</td></tr><tr><td>改 remote</td><td>相同</td><td>相同</td></tr><tr><td>加 <code>--force</code></td><td>相同</td><td>相同</td></tr><tr><td>改成 <code>--delete</code></td><td>相同</td><td>相同</td></tr><tr><td>只换 Session</td><td>相同</td><td><strong>不同</strong></td></tr><tr><td>改 TASK</td><td>不同</td><td>不同</td></tr></tbody></table><p>这里不是找到了 SHA-256 的密码学碰撞。前四种动作变化经过适配以后，生成的审批 request 已经没有字段差异。<strong>不同输入先被压成相同对象，哈希只是忠实地给相同对象生成相同值。</strong></p><p>改 TASK 的负对照很重要：不是函数对所有输入都返回常量，而是某些关键语义没有进入它。</p><p>我们还直接调用了实际 Codex 原生审批请求对应的本地 resolution 函数。原命令和改分支两种情况各重复两轮，均得到允许结果，批准被消费。它把观察推进到了产品的 Codex 审批解析入口，但没有启动 Codex app-server，也没有发送真实批准响应或执行推送。</p><p>需要严格区分：<strong>改 remote、force、delete 验证到了摘要相同；改分支进一步验证到了批准消费。</strong> 不能把前者全部写成已经执行了相应操作。</p><p>这也解释了为什么“一次消费”不能独自守住这条边界。它回答的是“这份批准有没有用过”，不是“用它的动作是不是批准的那个”。</p><h2 id="_4-session-从顶层排除了-又从快照里回来了" tabindex="-1">4. Session 从顶层排除了，又从快照里回来了 <a class="header-anchor" href="#_4-session-从顶层排除了-又从快照里回来了" aria-label="Permalink to &quot;4. Session 从顶层排除了，又从快照里回来了&quot;">​</a></h2><p>反方向的异常发生在另一个字段上。</p><p>底层 <code>computeOperationDigest</code> 明确排除了请求顶层的 <code>subject.session_id</code>。这与既有 Session 续接测试相符：相同操作不一定必须由原会话完成。</p><p>实际请求构造却同时把完整的操作事实放进了快照。只换 Session 时，请求出现两个差异：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>subject.session_id</span></span>
<span class="line"><span>snapshot.operation_facts.subject.session_id</span></span></code></pre></div><p>第一处被摘要函数排除了，第二处没有。</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/nested-session.zh.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/nested-session.zh.png" alt="图 2：顶层 Session 被排除，嵌套 Session 仍进入摘要"></a></p><p><em>图 2：命令不变时，嵌套 Session 仍可改变请求摘要。来源：本次真实请求差分与内存反事实检查；S1/S2 是示意标识，不是实际会话编号，也不是删除全部会话绑定的修复建议。点击图片查看高清原图。</em></p><p>结果是：操作指纹保持不变，请求摘要却发生变化。消费服务还没走到后面的身份条件核验，就无法按摘要选中那份原批准。批准记录虽然登记了新的唤醒会话，仍停留在 available。</p><p>我们做了一个内存中的反事实检查：仅从两份请求快照移除第二份 Session 字段，再调用原摘要函数。原会话与新会话的摘要这时才相同。这个检查用于定位差异来源，没有修改产品，也没有把处理后的请求拿去执行。</p><p>它更不是“递归删除所有 session_id”的修复建议。有些操作对临时目录归属、当前执行者或会话权限确实敏感，那些绑定不能顺手删掉。</p><p>真正需要区分的是：<strong>哪些字段定义动作，哪些字段记录这次运行，又有哪些字段必须在当前执行时重新核验。</strong></p><p>测试落差也由此清楚了。底层单测构造了一份较简洁的审批请求；真实入口多带了一份包含 Session 的事实快照。两者都叫“同动作换会话”，输入形状却不是同一个。</p><h2 id="_5-授权身份需要经得住两个方向的变异" tabindex="-1">5. 授权身份需要经得住两个方向的变异 <a class="header-anchor" href="#_5-授权身份需要经得住两个方向的变异" aria-label="Permalink to &quot;5. 授权身份需要经得住两个方向的变异&quot;">​</a></h2><p>这两个现象不应该分别用“多加字段”和“少加字段”草率修补。</p><p>全量哈希并不自动安全：它可能把运行噪声带进动作身份。粗粒度分类也不够：它可能让不同动作共享批准范围。</p><p>对需要精确批准的执行入口，我们建议把以下问题带进工程评审，而不是先决定重构规模：</p><p><strong>第一，改变动作含义时，批准匹配必须失效。</strong> 对 Git，这不仅是“还是不是 push”，还涉及目标仓库或 remote、引用与更新模式，以及该批准要求固定的其他条件。规范化之前丢失的信息，不能指望摘要补回来。</p><p><strong>第二，允许变化的运行上下文，不能偶然改变动作身份。</strong> 这不意味着新 Session 自动有权执行。动作匹配成立以后，仍要核验当前调用者、授权状态和适用范围；一份旧 receipt 不是新的执行许可。</p><p><strong>第三，要在真实请求生产者与消费者之间测。</strong> 不只手写一份理想 CapabilityRequest，再证明消费函数正确。把原始工具参数交给实际适配器，观察它最终批准和匹配的对象是什么。</p><p>一个小而有用的测试组合是：原动作正对照、改变目标、改变模式、允许的上下文续接、改变 TASK/执行者、取消批准、重复消费。两类关键变异的预期方向相反：该失配的必须失配；允许保持身份的，应当稳定，同时保留当前授权复核。</p><p>本轮研究还检查了另一种身份问题：两份正文完全相同、task_id 不同的任务，子任务是否会把错误的那个当作依赖。六种父子/依赖情况重复两轮，现有 FCoP 检查符合预期。这个通过结果限定了改造范围：<strong>现在有证据需要收紧的是操作授权身份，不是把整个任务身份体系推倒重来。</strong></p><h2 id="_6-这份结论到哪里为止" tabindex="-1">6. 这份结论到哪里为止 <a class="header-anchor" href="#_6-这份结论到哪里为止" aria-label="Permalink to &quot;6. 这份结论到哪里为止&quot;">​</a></h2><p>本文没有线上事故样本，也没有故障频率统计。数字来自固定提交上的受控实验；既有测试、字段比较、审批入口观察是不同集合，不能相加成一个“系统可靠率”。</p><p>我们确认了两项局部缺口：受测 shell Git 路径丢失具体动作差异，以及真实请求中的嵌套 Session 破坏预期续接匹配。未证明匿名攻击、真实远端损失、所有工具同样受影响，或一次完整恢复调度必然触发这些现象。上游 Guardian 变更只作方法对照，未在本轮独立复跑。</p><p>当前状态是<strong>研究完成、建议进入工程评审</strong>。本文不宣布修复、合同冻结或开发授权。配套<a href="/joinwell52/zh/research/evidence/2026-09-04-approval-operation-identity">证据包</a>提供去标识逐轮观察、主张映射与读取校验器；校验器检查记录一致性，不冒充重新运行产品或独立 QA。完整原始夹具及产品源码复跑环境仍是本地研究材料，未随此稿发布；不能把附包称为读者可直接执行的完整产品复现环境。</p><p>最终留下的问题很简单：</p><p><strong>一份批准只用了一次，还不够。系统必须先证明：用掉它的，正是被批准的那个动作。</strong></p>`,70))])}const _=p(r,[["render",l]]);export{m as __pageData,_ as default};
